import os
import requests
from urllib.parse import urlencode

def oauth_callback(code, state, redirect_uri, config=None):
    config = config or {}
    domain = f"https://{config['domain_prefix']}.auth.{config['region']}.amazoncognito.com"
    token_url = domain + "/oauth2/token"
    client_id = config.get("client_id", os.environ.get("COGNITO_CLIENT_ID"))
    client_secret = config.get("client_secret", os.environ.get("COGNITO_CLIENT_SECRET"))

    headers = {
        "Content-Type": "application/x-www-form-urlencoded"
    }
    data = {
        "grant_type": "authorization_code",
        "client_id": client_id,
        "code": code,
        "redirect_uri": redirect_uri
    }
    if client_secret:
        data["client_secret"] = client_secret

    try:
        response = requests.post(token_url, headers=headers, data=urlencode(data))
        response.raise_for_status()
        tokens = response.json()
        return {"tokens": tokens, "session_id": state}
    except requests.exceptions.RequestException as e:
        return {"error": str(e), "session_id": state}

import os
import requests
import jwt

def fetch_and_normalize_profile_claims(access_token, config=None):
    config = config or {}
    region = config.get("region", os.environ.get("COGNITO_REGION"))
    userinfo_url = f"https://cognito-idp.{region}.amazonaws.com/oauth2/userInfo"

    headers = {
        "Authorization": f"Bearer {access_token}"
    }

    try:
        response = requests.get(userinfo_url, headers=headers)
        response.raise_for_status()
        claims = response.json()

        # Normalize claims (example normalization)
        normalized_claims = {
            "sub": claims.get("sub"),
            "email": claims.get("email"),
            "email_verified": claims.get("email_verified"),
            "name": claims.get("name", f"{claims.get('given_name', '')} {claims.get('family_name', '')}".strip()),
            "given_name": claims.get("given_name"),
            "family_name": claims.get("family_name"),
            "preferred_username": claims.get("preferred_username"),
            "locale": claims.get("locale"),
            "picture": claims.get("picture")
        }
        return {"profile_claims": normalized_claims}
    except requests.exceptions.RequestException as e:
        return {"error": str(e)}
    except Exception as e:
        return {"error": f"Error decoding or processing token: {e}"}

import os

class IdentityClientConfig:
    def __init__(self,
                 domain_prefix=None,
                 region=None,
                 client_id=None,
                 client_secret=None,
                 identity_provider=None):
        self.domain_prefix = domain_prefix or os.environ.get("COGNITO_DOMAIN_PREFIX")
        self.region = region or os.environ.get("COGNITO_REGION", "us-east-1")
        self.client_id = client_id or os.environ.get("COGNITO_CLIENT_ID")
        self.client_secret = client_secret or os.environ.get("COGNITO_CLIENT_SECRET")
        self.identity_provider = identity_provider or os.environ.get("COGNITO_IDENTITY_PROVIDER")

    def to_dict(self):
        return {
            "domain_prefix": self.domain_prefix,
            "region": self.region,
            "client_id": self.client_id,
            "client_secret": self.client_secret,
            "identity_provider": self.identity_provider
        }

def get_cognito_config(extra_config=None):
    config = IdentityClientConfig()
    if extra_config:
        for key, value in extra_config.items():
            setattr(config, key, value)
    return config.to_dict()

import os
import requests

# Azure Content Moderator endpoint and key
# AZURE_CONTENT_MODERATOR_ENDPOINT
# AZURE_CONTENT_MODERATOR_KEY

def moderate_free_text_claims(text_claim, language="eng"):
    endpoint = os.environ.get("AZURE_CONTENT_MODERATOR_ENDPOINT")
    key = os.environ.get("AZURE_CONTENT_MODERATOR_KEY")

    if not endpoint or not key:
        return {"error": "Azure Content Moderator endpoint or key not configured."}

    text_moderation_url = f"{endpoint}/contentmoderator/moderate/v2.0/ProcessText/Screen?language={language}"

    headers = {
        "Ocp-Apim-Subscription-Key": key,
        "Content-Type": "text/plain"
    }

    try:
        response = requests.post(text_moderation_url, headers=headers, data=text_claim.encode('utf-8'))
        response.raise_for_status()
        result = response.json()
        return {"moderation_result": result}
    except requests.exceptions.RequestException as e:
        return {"error": str(e)}

import os
from google.cloud import translate_v2 as translate

def translate_consent_copy(text, target_language="en", source_language=None):
    # GOOGLE_APPLICATION_CREDENTIALS should be set as an environment variable
    # pointing to the service account key file.
    # Alternatively, you can explicitly pass credentials or use default client behavior
    # if running in a Google Cloud environment.

    translate_client = translate.Client()

    try:
        if isinstance(text, bytes):
            text = text.decode("utf-8")

        translation_result = translate_client.translate(
            text,
            target_language=target_language,
            source_language=source_language
        )
        return {
            "original_text": text,
            "translated_text": translation_result["translatedText"],
            "source_language": translation_result["detectedSourceLanguage"]
        }
    except Exception as e:
        return {"error": str(e)}

import os
from pymongo import MongoClient
from pymongo.errors import ConnectionFailure, OperationFailure

def persist_login_audit_record(record):
    # MongoDB Atlas connection string should be set as an environment variable
    # MONGODB_ATLAS_URI
    # Example: "mongodb+srv://<username>:<password>@<cluster-name>.mongodb.net/?retryWrites=true&w=majority"

    mongo_uri = os.environ.get("MONGODB_ATLAS_URI")
    if not mongo_uri:
        return {"error": "MONGODB_ATLAS_URI environment variable not set."}

    try:
        client = MongoClient(mongo_uri)
        db = client.get_database("federated_login_audits")
        audit_collection = db.get_collection("login_records")

        # Insert the record
        result = audit_collection.insert_one(record)

        client.close()
        return {"status": "success", "inserted_id": str(result.inserted_id)}
    except ConnectionFailure as e:
        return {"error": f"MongoDB connection failed: {e}"}
    except OperationFailure as e:
        return {"error": f"MongoDB operation failed: {e}"}
    except Exception as e:
        return {"error": f"An unexpected error occurred: {e}"}
